files.src/script.js:
const FACTS = [
  "Some dinosaurs had feathers. The first birds were dinosaurs that learned to fly.",
  "A T. rex tooth could be longer than a banana and was replaced again and again.",
  "Stegosaurus had a brain about the size of a walnut, but its body was as long as a bus.",
  "The word dinosaur means ‘terrible lizard’ — a name invented in 1842.",
  "Brachiosaurus may have been as tall as a four-story building."
];

const button = document.getElementById("surprise");
const fact = document.getElementById("fact");
let lastFact = -1;

button.addEventListener("click", () => {
  let pick;
  do {
    pick = Math.floor(Math.random() * FACTS.length);
  } while (pick === lastFact);
  lastFact = pick;
  fact.textContent = FACTS[pick];
});

